jQuery(document).ready(function(t){t('a[href*="#"]:not([href="#"])').click(function(){if(location.pathname.replace(/^\//,"")==this.pathname.replace(/^\//,"")&&location.hostname==this.hostname){var n=t(this.hash);if(n=n.length?n:t("[name="+this.hash.slice(1)+"]"),n.length)return t("html, body").animate({scrollTop:n.offset().top},500),!1}}),t(".pageTop").click(function(){return t("html, body").animate({scrollTop:0},500),!1}),t(".navBtn, .close_sp, .navi_sp li a").click(function(){t("body").toggleClass("layerMenuOn")}),t(".menu-trigger").on("click",function(){t(this).toggleClass("active")})});